/* Owned teaching pool: at most 256 sleeping threads, stdin control, no child forks. */
#include <pthread.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
static pthread_mutex_t lock=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t changed=PTHREAD_COND_INITIALIZER;
static int active=256;
static pthread_t workers[256];
static void *worker(void *arg){
    int index=(int)(intptr_t)arg;
    pthread_mutex_lock(&lock);
    while(index<active)pthread_cond_wait(&changed,&lock);
    pthread_mutex_unlock(&lock);return NULL;
}
static void *probe(void *arg){(void)arg;return NULL;}
int main(void){
    pthread_attr_t attributes;pthread_attr_init(&attributes);
    if(pthread_attr_setstacksize(&attributes,131072))return 3;
    int count=0,code=0;
    for(;count<256;count++){code=pthread_create(&workers[count],&attributes,worker,(void *)(intptr_t)count);if(code)break;}
    printf("{\"workers\":%d,\"create_error\":%d}\n",count,code);fflush(stdout);
    char line[64];
    while(fgets(line,sizeof(line),stdin)){
        if(strncmp(line,"limit ",6)==0){
            int target=atoi(line+6);if(target<0||target>count)return 4;
            pthread_mutex_lock(&lock);active=target;pthread_cond_broadcast(&changed);pthread_mutex_unlock(&lock);
            for(int i=target;i<count;i++)pthread_join(workers[i],NULL);
            count=target;printf("{\"workers\":%d}\n",count);
        }else if(strncmp(line,"probe",5)==0){
            pthread_t thread;code=pthread_create(&thread,&attributes,probe,NULL);
            if(!code)pthread_join(thread,NULL);
            printf("{\"probe_error\":%d}\n",code);
        }else if(strncmp(line,"stop",4)==0)break;
        else return 5;
        fflush(stdout);
    }
    pthread_mutex_lock(&lock);active=0;pthread_cond_broadcast(&changed);pthread_mutex_unlock(&lock);
    for(int i=0;i<count;i++)pthread_join(workers[i],NULL);
    pthread_attr_destroy(&attributes);return 0;
}

