import sys,os,pathlib,tempfile,subprocess,json,select,errno,time
sys.path.insert(0,str(pathlib.Path.cwd()));import task
assert sys.platform=='linux' and os.geteuid()!=0
cgroup=pathlib.Path('/sys/fs/cgroup');maximum=(cgroup/'pids.max').read_text().strip()
if not maximum.isdecimal() or not 32<=int(maximum)<=256:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: requires dedicated isolated cgroup with bounded pids.max 32..256; do not change host limits')
maximum=int(maximum);beforelimit=(cgroup/'pids.max').read_bytes()
def current():return int((cgroup/'pids.current').read_text())
def events():return int(dict(row.split() for row in (cgroup/'pids.events').read_text().splitlines())['max'])
print('NATIVE_LINUX_READY',flush=True)
with tempfile.TemporaryDirectory(prefix='of-pids-') as directory:
 root=pathlib.Path(directory);executable=root/'owned-pool'
 compilation=subprocess.run(['gcc','-O2','-pthread','checks/owned_pool.c','-o',str(executable)],capture_output=True,text=True,timeout=8)
 assert compilation.returncode==0,compilation.stderr
 baseline=current();old_events=events()
 process=subprocess.Popen([str(executable)],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
 try:
  def receive():
   assert select.select([process.stdout],[],[],3)[0],'owned pool response deadline'
   line=process.stdout.readline();assert line,'owned pool exited unexpectedly'
   return json.loads(line)
  def command(text):process.stdin.write(text+'\n');process.stdin.flush();return receive()
  exhausted=receive();workers=exhausted['workers']
  assert exhausted['create_error']==errno.EAGAIN and current()==maximum and events()>old_events,exhausted
  assert command('probe')['probe_error']==errno.EAGAIN
  print('NATIVE_CGROUP_PIDS_MAX_REACHED_AND_PTHREAD_CREATE_EAGAIN',flush=True)
