  for args in [(True,occupied,maximum,16),(workers,workers-1,maximum,16),(workers,occupied,maximum,0),(1,maximum,maximum,64)]:
   try:task.recover_pool(resize,*args)
   except ValueError:pass
   else:raise AssertionError('invalid/impossible budget accepted')
  assert calls==[]
  print('NATIVE_POOL_REDUCED_WITH_HEADROOM_AND_THREAD_CREATION_RECOVERED',flush=True)
 finally:
